def aplana(datos: list) -> list:
    result = []

    def _flatten(obj):
        if isinstance(obj, (list, tuple)):
            for item in obj:
                _flatten(item)
        else:
            result.append(obj)

    _flatten(datos)
    return result

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

from collections import OrderedDict

class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("La capacidad no puede ser negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        # Marcar como usado recientemente
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        if self.capacidad == 0:
            return
        if clave in self._datos:
            # Actualizar valor y marcar como usado
            self._datos[clave] = valor
            self._datos.move_to_end(clave)
        else:
            # Si la caché está llena, descartar el menos reciente
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
            # Insertar nuevo elemento
            self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
